
:global(*) {
  box-sizing: border-box;
}

:global(body) {
  margin: 0;
  min-width: 0;
  background: #fffaf8;
  color: #4f3e46;
  font-family: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
}

:global(button),
:global(input) {
  font: inherit;
}

:global(button) {
  cursor: pointer;
}

.intro-shell {
  --ink: #4f3e46;
  --muted: #8d737d;
  --line: #ead8dc;
  --soft-line: #f2e7e8;
  --paper: #fffdfb;
  --pink: #d9899e;
  --pink-deep: #a95773;
  --pink-soft: #fbecef;
  --sage: #8ba59c;
  --cream: #fff6ed;
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 13px;
  width: min(100%, 780px);
  min-height: 100vh;
  margin: 0 auto;
  overflow: hidden;
  padding: 30px 24px 24px;
  background: #fffaf8;
}

.ambient {
  position: absolute;
  z-index: -1;
  width: 150px;
  height: 150px;
  border: 1px solid rgba(217, 137, 158, 0.22);
  border-radius: 50%;
  pointer-events: none;
  animation: float-slow 8s ease-in-out infinite;
}

.ambient-one {
  top: 110px;
  right: -70px;
}

.ambient-two {
  bottom: 120px;
  left: -95px;
  width: 190px;
  height: 190px;
  border-color: rgba(139, 165, 156, 0.22);
  animation-delay: -3s;
}

.ornament-top {
  position: absolute;
  top: 16px;
  right: 28px;
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--pink);
  font-family: Georgia, serif;
  font-size: 12px;
  letter-spacing: 0;
  opacity: 0.75;
}

.ornament-top i {
  display: block;
  width: 22px;
  height: 1px;
  background: var(--line);
}

.intro-header {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
  padding: 16px 4px 14px;
}

.brand-mark {
  position: relative;
  flex: 0 0 58px;
  width: 58px;
  height: 58px;
  color: var(--pink-deep);
}

.brand-star,
.brand-heart {
  position: absolute;
  display: block;
  font-family: Georgia, serif;
}

.brand-star {
  top: -4px;
  left: 3px;
  color: var(--sage);
  font-size: 16px;
  animation: twinkle 2.8s ease-in-out infinite;
}

.brand-heart {
  right: 2px;
  bottom: -2px;
  font-size: 42px;
  line-height: 1;
  animation: breathe 3.8s ease-in-out infinite;
}

.brand-ring {
  position: absolute;
  top: 14px;
  left: 11px;
  width: 31px;
  height: 31px;
  border: 1px solid var(--pink);
  border-radius: 50%;
}

.brand-copy {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--pink-deep);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  line-height: 1.4;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-family: Georgia, 'Songti SC', serif;
  font-size: 31px;
  font-weight: 500;
  line-height: 1.15;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.world-note {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.note-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--pink);
  box-shadow: 0 0 6px rgba(217, 137, 158, 0.7);
}

.intro-block {
  padding: 14px 16px 15px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: 0 1px 0 var(--soft-line), 0 8px 22px rgba(169, 87, 115, 0.07);
}

.block-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}

.block-head h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  color: var(--ink);
  font-size: 13.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.block-glyph {
  color: var(--pink);
  font-family: Georgia, serif;
  font-size: 13px;
}

.block-hint {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.75;
}

.mini-button {
  padding: 3px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  font-size: 10.5px;
  letter-spacing: 0.04em;
  transition:
    color 0.2s ease,
    border-color 0.2s ease,
    background-color 0.2s ease,
    transform 0.12s ease;
}

.mini-button:hover {
  border-color: var(--pink);
  color: var(--pink-deep);
  background: var(--pink-soft);
}

.mini-button:focus-visible {
  border-color: var(--pink-deep);
  color: var(--pink-deep);
  outline: 2px solid var(--pink-deep);
  outline-offset: 2px;
}

.mini-button:active {
  transform: translateY(1px);
}

.check-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.check-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: #fff;
  transition:
    border-color 0.35s ease,
    background-color 0.35s ease;
}

.check-light {
  position: relative;
  flex: 0 0 12px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transition:
    background-color 0.35s ease,
    box-shadow 0.35s ease;
}

.check-light::after {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  content: '';
  opacity: 0.28;
  transition: background-color 0.35s ease;
}

.check-copy {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.check-copy strong {
  color: var(--ink);
  font-size: 12.5px;
}

.check-copy strong em {
  margin-left: 6px;
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
  letter-spacing: 0.02em;
}

.check-copy small {
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.5;
}

.check-verdict {
  flex: 0 0 auto;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.check-card.is-ok {
  border-color: #cfe3d3;
  background: #f5fbf6;
}

.check-card.is-ok .check-light {
  background: #55b476;
  box-shadow: 0 0 8px rgba(85, 180, 118, 0.65);
}

.check-card.is-ok .check-light::after {
  background: #55b476;
}

.check-card.is-ok .check-verdict {
  color: #3f8f5c;
}

.check-card.is-missing {
  border-color: #f0d2d2;
  background: #fff8f8;
}

.check-card.is-missing .check-light {
  background: #d96459;
  box-shadow: 0 0 8px rgba(217, 100, 89, 0.6);
}

.check-card.is-missing .check-light::after {
  background: #d96459;
}

.check-card.is-missing .check-verdict {
  color: #c05046;
}

.link-grid {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.link-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 13px;
  border: 1px dashed var(--pink);
  border-radius: 11px;
  background: linear-gradient(120deg, var(--pink-soft), #fff 68%);
  color: inherit;
  text-decoration: none;
  transition:
    transform 0.12s ease,
    border-color 0.22s ease;
}

.link-card:hover {
  border-color: var(--pink-deep);
  border-style: solid;
}

.link-card:focus-visible {
  border-color: var(--pink-deep);
  border-style: solid;
  outline: 2px solid var(--pink-deep);
  outline-offset: 2px;
}

.link-card:active {
  transform: translateY(1px);
}

.link-glyph {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--pink-deep);
  font-family: Georgia, serif;
  font-size: 15px;
  box-shadow: inset 0 0 0 1px var(--line);
}

.link-copy {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.link-copy strong {
  color: var(--ink);
  font-size: 12.5px;
}

.link-copy small {
  color: var(--muted);
  font-size: 10.5px;
}

.link-arrow {
  color: var(--pink);
  font-size: 14px;
}

.guide-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: guide;
}

.guide-list li {
  display: flex;
  align-items: baseline;
  gap: 10px;
  color: var(--ink);
  font-size: 12px;
  line-height: 1.65;
}

.guide-list li::before {
  flex: 0 0 auto;
  color: var(--pink);
  font-family: Georgia, serif;
  font-size: 11px;
  letter-spacing: 0.05em;
  content: '0' counter(guide);
  counter-increment: guide;
}

.guide-list b {
  flex: 0 0 auto;
  font-weight: 700;
  white-space: nowrap;
}

.guide-list span {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--muted);
  font-size: 11.5px;
}

.cleanup-block {
  background: linear-gradient(165deg, var(--cream), var(--paper) 72%);
}

.cleanup-note {
  margin: 0 0 11px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.8;
}

.cleanup-button {
  padding: 9px 18px;
  border: 1px solid var(--pink);
  border-radius: 999px;
  background: #fff;
  color: var(--pink-deep);
  font-size: 12px;
  letter-spacing: 0.04em;
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease,
    transform 0.12s ease;
}

.cleanup-button:hover:not(:disabled) {
  background: var(--pink-soft);
}

.cleanup-button:focus-visible:not(:disabled) {
  background: var(--pink-soft);
  outline: 2px solid var(--pink-deep);
  outline-offset: 2px;
}

.cleanup-button:active:not(:disabled) {
  transform: translateY(1px);
}

.cleanup-button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.cleanup-button.is-confirm {
  border-color: #d96459;
  background: #d96459;
  color: #fff;
  animation: cleanup-alert 420ms ease-out both;
}

.cleanup-button.is-done {
  border-color: var(--sage);
  color: #4f7d6d;
}

.cleanup-status {
  margin: 9px 0 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.75;
}

.primary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-width: 126px;
  min-height: 42px;
  padding: 8px 16px;
  border: 1px solid var(--pink-deep);
  border-radius: 5px;
  background: var(--pink-deep);
  color: #fffdfb;
  font-size: 12px;
  box-shadow: 0 6px 14px rgba(169, 87, 115, 0.16);
  transition:
    transform 0.12s ease,
    background-color 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease;
}

.primary-button:hover:not(:disabled) {
  background: #934863;
}

.primary-button:focus-visible:not(:disabled) {
  background: #934863;
  outline: 2px solid #934863;
  outline-offset: 3px;
}

.primary-button:active:not(:disabled) {
  transform: translateY(1px);
}

.primary-button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.button-arrow {
  font-family: Georgia, serif;
  font-size: 17px;
}

.intro-start {
  margin: 4px auto 0;
  width: min(100%, 340px);
}

.swipe-hint {
  margin: 0 0 6px;
  color: var(--muted);
  font-size: 10.5px;
  letter-spacing: 0.04em;
  text-align: center;
}

@keyframes float-slow {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }
  50% {
    transform: translate3d(0, 10px, 0);
  }
}

@keyframes twinkle {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.9) rotate(0deg);
  }
  50% {
    opacity: 1;
    transform: scale(1.12) rotate(12deg);
  }
}

@keyframes breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.04);
  }
}

@keyframes cleanup-alert {
  from {
    opacity: 0.82;
    transform: translateY(1px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (max-width: 620px) {
  .intro-shell {
    padding: 24px 14px 18px;
  }

  .intro-header {
    flex-wrap: wrap;
    gap: 12px;
  }

  .world-note {
    display: none;
  }

  h1 {
    font-size: 27px;
  }

  .intro-block {
    padding: 12px 13px 13px;
  }

  .check-card {
    flex-wrap: wrap;
  }

  .check-verdict {
    flex: 1 1 100%;
    padding-left: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
  }
}
